import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter is a space-efficient probabilistic data structure 
    that is used to test whether an element is a member of a set. False positives are possible, 
    but false negatives are not. This class implements a basic Bloom Filter with methods to add items 
    and to check for their existence. The optimal bit array size and number of hash functions 
    are calculated based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array
        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        # Calculate the optimal number of hash functions
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the given item."""
        return [
            int(hashlib.md5((f"{item}{i}").encode()).hexdigest(), 16) % self.size
            for i in range(self.hash_count)
        ]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_index in self._hashes(item):
            self.bit_array[hash_index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_index] for hash_index in self._hashes(item))

