class BloomFilter:
    """
    This Bloom Filter class uses a combination of MD5 hashing and manual array management 
    for tracking added items in a bit array. The design leverages bit manipulation to 
    store and retrieve information efficiently. The bit array size and hash functions 
    are optimized based on the expected item count and the specified false positive rate.
    The approach emphasizes controlled randomness in hashing and operational efficiency.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        self.bit_array = 0  # Using an integer for bit manipulation

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal bit array size for the bloom filter."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _get_hash_indices(self, item: str) -> list:
        """Compute hash indices for a given item using MD5."""
        hashes = []
        for i in range(self.hash_count):
            md5_hash = hashlib.md5((item + str(i)).encode()).hexdigest()
            index = int(md5_hash, 16) % self.size
            hashes.append(index)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._get_hash_indices(item):
            self.bit_array |= (1 << index)  # Set the bit at index to 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all((self.bit_array & (1 << index)) > 0 for index in self._get_hash_indices(item))

import hashlib
import math

class BloomFilter:
    """
    This Bloom Filter class employs a fixed-size byte array for storing bits and uses custom hashing 
    methods to determine the positions in the array. The algorithm first computes the optimal size 
    of the bit array and the number of hash functions based on the input parameters. It focuses on 
    memory efficiency and the uniqueness of hash outputs to minimize collisions while achieving 
    the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        self.bit_array = bytearray((self.size // 8) + (1 if self.size % 8 else 0))

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array based on expected items and false positive rate."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Determine the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _get_hash_indices(self, item: str) -> list:
        """Generate indices from the input item using SHA-256 hashing."""
        indices = set()
        for i in range(self.hash_count):
            hash_object = hashlib.sha256((item + str(i)).encode())
            hash_digest = hash_object.hexdigest()
            index = int(hash_digest, 16) % self.size
            indices.add(index)
        return list(indices)

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._get_hash_indices(item):
            byte_index = index // 8
            bit_position = index % 8
            self.bit_array[byte_index] |= (1 << bit_position)

    def contains(self, item: str) -> bool:
        """Check if an item exists in the Bloom Filter."""
        return all(self.bit_array[index // 8] & (1 << (index % 8)) for index in self._get_hash_indices(item))
